$geojson$::jsonb as j)
insert into public.boundaries (name, source, version, is_active, geom)
select 'Област Сливен',
       'OpenStreetMap relation ' || (j->'features'->0->'properties'->>'osm_id')
         || ', ODbL, ' || to_char(now(), 'YYYY-MM-DD'),
       1,
       true,
       extensions.st_multi(extensions.st_setsrid(
         extensions.st_geomfromgeojson((j->'features'->0->'geometry')::text), 4326))
from src;

-- Защита: площта трябва да е около 3 544 km² (област Сливен)
do $$
declare
  km2 numeric;
begin
  select extensions.st_area(geom::extensions.geography) / 1e6 into km2
  from public.boundaries where is_active;
  if km2 is null or km2 < 3000 or km2 > 4200 then
    raise exception 'Площта е % km2, а се очакват 3000-4200. Вероятно е взет друг обект (община, градът или по-голям район).', round(coalesce(km2, 0));
  end if;
end $$;